INSERT INTO notification_mail_template (created_at, updated_at, version, name, owner, updated_by, subject, description, body_html) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 'Veri seti tablosu (örnek)', 'admin', 'admin', '{{flow.name}} - {{run.date}}', 'Veri setinin ilk satırları tablo olarak, CSV eki', '<h2>{{flow.name}}</h2>{{^steps.dataset.hasRows}}<p>Bu sefer kayıt yok.</p>{{/steps.dataset.hasRows}}{{#steps.dataset.hasRows}}<p>{{steps.dataset.rowCount}} kayıt</p><table border="1" cellpadding="4"><tr>{{#steps.dataset.columns}}<th>{{.}}</th>{{/steps.dataset.columns}}</tr>{{#steps.dataset.rows}}<tr>{{#cells}}<td>{{.}}</td>{{/cells}}</tr>{{/steps.dataset.rows}}</table>{{#steps.dataset.previewTruncated}}<p>İlk satırlar gösteriliyor; tamamı ektedir.</p>{{/steps.dataset.previewTruncated}}{{/steps.dataset.hasRows}}');
INSERT INTO notification_mail_template (created_at, updated_at, version, name, owner, updated_by, subject, description, body_html) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 'Bilgilendirme (örnek)', 'admin', 'admin', '{{flow.name}}', 'Akış adı ve çalışma numarası', '<p><b>{{flow.name}}</b></p><p>Çalışma #{{run.id}} · {{run.date}}</p>');
