INSERT INTO flow_definition (created_at, updated_at, version, name, owner, updated_by, description, definition_json) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 'Haftalık departman kadrosu', 'admin', 'admin', 'Her pazartesi 08:00: departman bazında aktif çalışan sayısı ve maaş, CSV ekli mail.', '{"steps": [{"type": "dataset", "key": "dataset", "definition": {"root": "Personnel", "columns": [{"field": "department.name"}, {"aggregate": "COUNT", "label": "Headcount"}, {"field": "salary", "aggregate": "AVG", "label": "Average Salary"}, {"field": "salary", "aggregate": "MAX", "label": "Top Salary"}], "where": {"field": "active", "operator": "EQ", "value": true}, "having": {"aggregate": "COUNT", "operator": "GTE", "value": 3}, "sort": [{"field": "salary", "aggregate": "AVG", "direction": "DESC"}]}, "fileName": "departman-kadrosu.csv"}, {"type": "mail", "key": "mail", "templateId": ' || (SELECT id FROM notification_mail_template WHERE name = 'Veri seti tablosu (örnek)') || ', "to": ["yonetim@example.com"], "cc": [], "attachments": ["dataset"]}], "edges": [{"from": "dataset", "to": "mail", "when": null}], "layout": {"dataset": {"x": 0, "y": 0}, "mail": {"x": 320, "y": 0}}}');
INSERT INTO flow_step_reference (flow_id, kind, ref_id) SELECT f.id, 'mail-template', CAST(t.id AS VARCHAR(100)) FROM flow_definition f, notification_mail_template t WHERE f.name = 'Haftalık departman kadrosu' AND t.name = 'Veri seti tablosu (örnek)';
INSERT INTO flow_schedule (enabled, created_at, flow_id, next_fire_at, updated_at, version, time_zone, created_by, cron) SELECT TRUE, CURRENT_TIMESTAMP, id, DATEADD('DAY', 7, CURRENT_TIMESTAMP), CURRENT_TIMESTAMP, 0, 'Europe/Istanbul', 'admin', '0 8 * * MON' FROM flow_definition WHERE name = 'Haftalık departman kadrosu';
INSERT INTO flow_definition (created_at, updated_at, version, name, owner, updated_by, description, definition_json) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 'Zorunlu eğitim uyumu', 'admin', 'admin', 'Geciken ya da 30 gün içinde dolacak zorunlu eğitim varsa İK''ya liste gider; yoksa akış biter.', '{"steps": [{"type": "dataset", "key": "dataset", "definition": {"root": "TrainingRecord", "columns": [{"field": "personnel.department.name"}, {"field": "training.category"}, {"aggregate": "COUNT", "label": "Records"}, {"field": "personnel.fullName", "aggregate": "COUNT_DISTINCT", "label": "People"}, {"field": "score", "aggregate": "AVG", "label": "Average Score"}], "where": {"conditions": [{"field": "training.mandatory", "operator": "EQ", "value": true}, {"field": "status", "operator": "NOT_IN", "value": ["FAILED"]}, {"logic": "OR", "conditions": [{"field": "nextRenewalDate", "operator": "LAST_N_DAYS", "value": 365}, {"field": "nextRenewalDate", "operator": "NEXT_N_DAYS", "value": 30}]}]}, "having": {"aggregate": "COUNT", "operator": "GTE", "value": 1}, "sort": [{"aggregate": "COUNT", "direction": "DESC"}, {"field": "personnel.department.name"}]}, "fileName": "egitim-uyumu.csv"}, {"type": "condition", "key": "var_mi", "expression": {">": [{"var": "steps.dataset.rowCount"}, 0]}}, {"type": "mail", "key": "ik_mail", "templateId": ' || (SELECT id FROM notification_mail_template WHERE name = 'Veri seti tablosu (örnek)') || ', "to": ["ik@example.com"], "cc": [], "attachments": ["dataset"]}], "edges": [{"from": "dataset", "to": "var_mi", "when": null}, {"from": "var_mi", "to": "ik_mail", "when": "true"}], "layout": {"dataset": {"x": 0, "y": 0}, "var_mi": {"x": 320, "y": 0}, "ik_mail": {"x": 640, "y": 0}}}');
INSERT INTO flow_step_reference (flow_id, kind, ref_id) SELECT f.id, 'mail-template', CAST(t.id AS VARCHAR(100)) FROM flow_definition f, notification_mail_template t WHERE f.name = 'Zorunlu eğitim uyumu' AND t.name = 'Veri seti tablosu (örnek)';
INSERT INTO flow_definition (created_at, updated_at, version, name, owner, updated_by, description, definition_json) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 'Bütçe talebi onayı', 'admin', 'admin', 'Webhook ile gelen talep 10.000 ve üstüyse Finans onayına gider; sonuç talep sahibine bildirilir.', '{"steps": [{"type": "condition", "key": "buyuk_mu", "expression": {">=": [{"var": "trigger.amount"}, 10000]}}, {"type": "approval", "key": "finans_onayi", "groupId": ' || (SELECT id FROM approval_group WHERE name = 'Finans onay') || ', "title": "Bütçe talebi: {{trigger.amount}} TL", "description": "{{trigger.requester}} — {{trigger.reason}}", "timeoutHours": 48, "allowSelfApproval": false, "notifyMembers": true}, {"type": "mail", "key": "onaylandi", "templateId": ' || (SELECT id FROM notification_mail_template WHERE name = 'Bilgilendirme (örnek)') || ', "to": ["talep@example.com"], "cc": [], "attachments": []}, {"type": "mail", "key": "reddedildi", "templateId": ' || (SELECT id FROM notification_mail_template WHERE name = 'Bilgilendirme (örnek)') || ', "to": ["talep@example.com"], "cc": [], "attachments": []}, {"type": "mail", "key": "otomatik_onay", "templateId": ' || (SELECT id FROM notification_mail_template WHERE name = 'Bilgilendirme (örnek)') || ', "to": ["talep@example.com"], "cc": [], "attachments": []}], "edges": [{"from": "buyuk_mu", "to": "finans_onayi", "when": "true"}, {"from": "buyuk_mu", "to": "otomatik_onay", "when": "false"}, {"from": "finans_onayi", "to": "onaylandi", "when": "approved"}, {"from": "finans_onayi", "to": "reddedildi", "when": null}], "layout": {"buyuk_mu": {"x": 0, "y": 100}, "finans_onayi": {"x": 320, "y": 0}, "otomatik_onay": {"x": 320, "y": 260}, "onaylandi": {"x": 640, "y": 0}, "reddedildi": {"x": 640, "y": 170}}}');
INSERT INTO flow_step_reference (flow_id, kind, ref_id) SELECT f.id, 'mail-template', CAST(t.id AS VARCHAR(100)) FROM flow_definition f, notification_mail_template t WHERE f.name = 'Bütçe talebi onayı' AND t.name = 'Bilgilendirme (örnek)';
INSERT INTO flow_step_reference (flow_id, kind, ref_id) SELECT f.id, 'approval-group', CAST(t.id AS VARCHAR(100)) FROM flow_definition f, approval_group t WHERE f.name = 'Bütçe talebi onayı' AND t.name = 'Finans onay';
